 water)     P="$P; cmd fill 294 149 304 306 149 310 stone; cmd fill 294 150 304 306 150 304 stone; cmd fill 294 150 310 306 150 310 stone; cmd fill 294 150 304 294 150 310 stone; cmd fill 306 150 304 306 150 310 stone; cmd fill 295 150 305 305 150 309 water; cmd setblock 300 151 307 water; cmd setblock 297 151 305 water; cmd fill 295 149 306 305 149 306 blue_ice";;
 vegetation) P="$P; cmd fill 292 149 304 308 149 311 grass_block; cmd fill 292 150 304 308 150 311 short_grass; cmd fill 296 150 306 299 152 309 oak_leaves[persistent=true]; cmd fill 301 150 305 304 150 310 fern; cmd fill 303 150 307 306 152 309 vine; cmd fill 292 150 305 294 151 311 tall_grass; cmd setblock 300 150 306 oak_sapling";;
 transparency) P="$P; cmd fill 292 150 311 308 156 311 red_concrete; cmd fill 295 150 308 297 154 308 yellow_stained_glass; cmd fill 298 150 308 300 154 308 lime_stained_glass; cmd fill 301 150 308 303 154 308 blue_stained_glass; cmd fill 304 150 308 306 152 308 ice; cmd fill 295 150 306 297 151 306 honey_block; cmd fill 301 150 305 303 151 305 slime_block; cmd setblock 300 150 306 water; cmd summon sheep 296 150 310 {NoAI:1b,Silent:1b,Color:0}";;
 disocclusion) STRAFE=0.04; PR=0; YR=0; P="$P; cmd fill 289 149 311 313 160 311 white_concrete; cmd fill 293 150 311 293 160 311 red_concrete; cmd fill 297 150 311 297 160 311 blue_concrete; cmd fill 303 150 311 303 160 311 green_concrete; cmd fill 307 150 311 307 160 311 yellow_concrete; cmd fill 300 150 305 301 156 306 stone_bricks; cmd fill 304 150 303 304 154 304 oak_log; cmd fill 296 150 307 296 153 307 purple_concrete";;
